s = input().strip()
if len(s) % 2:
    print('NO')
else:
    low = high = 0
    possible = True
    for char in s:
        if char == '(':
            low += 1
            high += 1
        elif char == ')':
            low -= 1
            high -= 1
        else:
            low -= 1
            high += 1
        if high < 0:
            possible = False
            break
        low = max(low, 0)
    print('YES' if possible and low == 0 else 'NO')

