#include <algorithm>
#include <iostream>
#include <string>
using namespace std;
int main() { string s; cin >> s; if (s.size() % 2) { cout << "NO\n"; return 0; } int low = 0, high = 0; for (char c : s) { if (c == '(') ++low, ++high; else if (c == ')') --low, --high; else --low, ++high; if (high < 0) { cout << "NO\n"; return 0; } low = max(low, 0); } cout << (low == 0 ? "YES" : "NO") << '\n'; }
